                      payload?.[0]?.payload?.vintage ?? ""
                    }
                  />
                  <Line
                    type="monotone"
                    dataKey="top1Pct"
                    stroke={AMBER}
                    strokeWidth={2.5}
                    dot={{ r: 4 }}
                    name="top1Pct"
