                    ]}
                  />
                  <Area
                    type="monotone"
                    dataKey="sharePct"
                    fill={VIOLET}
                    fillOpacity={0.25}
                    stroke={VIOLET}
                    strokeWidth={2.5}
                    name="sharePct"
                  />
                  {showEqualLine && (
                    <Line
                      type="monotone"
                      dataKey="equalPct"
                      stroke={SLATE}
                      strokeDasharray="6 4"
                      strokeWidth={1.5}
                      dot={false}
                      name="equalPct"
                    />
                  )}
                </ComposedChart>
              </ResponsiveContainer>
            </div>
            <p className="mt-2 text-xs text-slate-500">
              Excludes S&amp;P uncommenced lease overhang (~$675B) ??? a parallel
              concentration story outside funded stock.
            </p>
          </ChartCard>
        </div>
      )}

      {view === "etf" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Thematic ETF inflow concentration"
            subtitle={`2025 US thematic sleeve ??? ${fmtBn(HEADLINE.thematicEtfFlowsBn)}`}
          >
            <div className="mb-3">
              <ToggleGroup
                label="Metric"
                value={etfMetric}
                onChange={setEtfMetric}
                options={[
                  { id: "sharePct", label: "Share %" },
